# Execute rating updates/creates to make rating=5 for songs in liked playlists

create_song_ids = []
update_review_ids = []  # list of review_id to update

for s in song_status:
    sid = s['song_id']
    if s['reviews_count'] == 0:
        create_song_ids.append(sid)
    else:
        # Update only reviews whose existing rating is < 5, pairing by index
        for i, rating in enumerate(s.get('ratings', [])):
            if rating is not None and float(rating) < 5.0:
                rid_list = s.get('review_ids', [])
                if i < len(rid_list):
                    update_review_ids.append(rid_list[i])

print('create_song_ids_count', len(create_song_ids))
print('update_review_ids_count', len(update_review_ids))

# For reporting, build mapping of review_id->song_id
review_id_to_song_id = {}
for s in song_status:
    for rid in s.get('review_ids', []):
        review_id_to_song_id[rid] = s['song_id']

# Perform updates
update_results = {'success':0, 'fail':0, 'errors':[]}
for rid in update_review_ids:
    try:
        res = apis.spotify.update_song_review(review_id=rid, access_token=spotify_token, rating=5)
        update_results['success'] += 1
    except Exception as e:
        update_results['fail'] += 1
        update_results['errors'].append({'review_id': rid, 'song_id': review_id_to_song_id.get(rid), 'error': str(e)})

print('update_results', update_results)

# Perform creates
create_results = {'success':0, 'fail':0, 'errors':[]}
for sid in create_song_ids:
    try:
        res = apis.spotify.review_song(song_id=sid, rating=5, access_token=spotify_token)
        create_results['success'] += 1
    except Exception as e:
        create_results['fail'] += 1
        create_results['errors'].append({'song_id': sid, 'error': str(e)})

print('create_results', create_results)

